package books

import (
	"context"
	"encore.dev/storage/sqldb"
)

var db = sqldb.NewDatabase("books", sqldb.DatabaseConfig{
	Migrations: "./migrations",
})

type Book struct {
	ID     int64  `json:"id"`
	Title  string `json:"title"`
	Author string `json:"author"`
}

//encore:api public method=POST path=/books
func AddBook(ctx context.Context, b *Book) (*Book, error) {
	row := db.QueryRow(ctx, `
		INSERT INTO books (title, author)
		VALUES ($1, $2)
		RETURNING id, title, author
	`, b.Title, b.Author)

	result := &Book{}
	err := row.Scan(&result.ID, &result.Title, &result.Author)
	if err != nil {
		return nil, err
	}
	return result, nil
}

//encore:api public method=GET path=/books
func ListBooks(ctx context.Context) ([]*Book, error) {
	rows, err := db.Query(ctx, `SELECT id, title, author FROM books`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var books []*Book
	for rows.Next() {
		b := &Book{}
		if err := rows.Scan(&b.ID, &b.Title, &b.Author); err != nil {
			return nil, err
		}
		books = append(books, b)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return books, nil
}
